"""Core service surface for PowerRail.

The baseline reports process health; battery state-of-charge estimation is
served from :meth:`Service.estimate_soc`. Keep the public surface here
backward compatible and express all client failures as :class:`ApiError`.
"""

from __future__ import annotations

import math
from typing import Any

from . import __version__

DEFAULT_REST_CURRENT_A = 0.05
DEFAULT_REST_DURATION_S = 300.0
DEFAULT_OCV_WEIGHT = 0.2


class ApiError(Exception):
    """Client error carrying an HTTP status and a stable machine-readable code."""

    def __init__(self, status: int, code: str, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.code = code
        self.message = message


def _is_finite_number(value: Any) -> bool:
    # ``bool`` is a subclass of ``int`` but is not a valid numeric reading.
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(value)
    )


def _interpolate_ocv(voltage: float, points: list[tuple[float, float]]) -> float:
    """Linearly interpolate SoC from a voltage-sorted OCV curve.

    Voltages outside the curve resolve to the nearest endpoint.
    """
    first_voltage, first_soc = points[0]
    last_voltage, last_soc = points[-1]
    if voltage <= first_voltage:
        return first_soc
    if voltage >= last_voltage:
        return last_soc
    for (v0, s0), (v1, s1) in zip(points, points[1:]):
        if voltage <= v1:
            ratio = (voltage - v0) / (v1 - v0)
            return s0 + ratio * (s1 - s0)
    return last_soc  # pragma: no cover - unreachable for a sorted curve


class Service:
    """Stateless service surface: health reporting and SoC estimation."""

    name = "powerrail"
    version = __version__

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def estimate_soc(self, payload: Any) -> dict[str, Any]:
        """Validate and run a coulomb-counting SoC estimate with OCV correction."""
        if not isinstance(payload, dict):
            raise ApiError(400, "invalid_json", "request body must be a JSON object")

        capacity = payload.get("capacity_ah")
        if not _is_finite_number(capacity) or capacity <= 0:
            raise ApiError(
                422, "invalid_capacity", "capacity_ah must be a positive finite number"
            )

        initial_soc = payload.get("initial_soc")
        if not _is_finite_number(initial_soc) or not 0 <= initial_soc <= 1:
            raise ApiError(
                422,
                "invalid_initial_soc",
                "initial_soc must be a finite number within [0, 1]",
            )

        samples = payload.get("samples")
        if not isinstance(samples, list) or not samples:
            raise ApiError(422, "invalid_samples", "samples must be a non-empty array")

        timestamps: list[float] = []
        previous_timestamp: float | None = None
        for sample in samples:
            if not isinstance(sample, dict):
                raise ApiError(
                    422,
                    "invalid_timestamp",
                    "each sample must be an object with a finite timestamp_s",
                )
            timestamp = sample.get("timestamp_s")
            if not _is_finite_number(timestamp):
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be a finite number"
                )
            if previous_timestamp is not None and timestamp <= previous_timestamp:
                raise ApiError(
                    422, "invalid_timestamp", "timestamp_s must be strictly increasing"
                )
            timestamps.append(timestamp)
            previous_timestamp = timestamp

        currents: list[float] = []
        voltages: list[float] = []
        for sample in samples:
            current = sample.get("current_a")
            voltage = sample.get("voltage_v")
            if not _is_finite_number(current) or not _is_finite_number(voltage):
                raise ApiError(
                    422,
                    "invalid_measurement",
                    "current_a and voltage_v must be finite numbers",
                )
            currents.append(current)
            voltages.append(voltage)

        ocv_points = self._parse_ocv_curve(payload.get("ocv_curve"))
        rest_current, rest_duration, ocv_weight = self._parse_options(payload)

        estimates: list[dict[str, Any]] = []
        soc = initial_soc
        rest_elapsed = 0.0
        capacity_seconds = capacity * 3600.0

        for index in range(len(samples)):
            timestamp = timestamps[index]
            if index == 0:
                estimates.append(
                    {"timestamp_s": timestamp, "soc": soc, "source": "coulomb"}
                )
                continue

            delta_time = timestamp - timestamps[index - 1]
            average_current = (currents[index - 1] + currents[index]) / 2.0
            soc_next = soc - average_current * delta_time / capacity_seconds
            if soc_next < 0.0:
                soc_next = 0.0
            elif soc_next > 1.0:
                soc_next = 1.0

            source = "coulomb"
            if ocv_points is not None:
                if (
                    abs(currents[index - 1]) <= rest_current
                    and abs(currents[index]) <= rest_current
                ):
                    rest_elapsed += delta_time
                else:
                    rest_elapsed = 0.0
                if rest_elapsed >= rest_duration:
                    ocv_soc = _interpolate_ocv(voltages[index], ocv_points)
                    soc_next = (
                        1.0 - ocv_weight
                    ) * soc_next + ocv_weight * ocv_soc
                    source = "ocv_corrected"

            soc = soc_next
            estimates.append(
                {"timestamp_s": timestamp, "soc": soc, "source": source}
            )

        return {"estimates": estimates, "final_soc": soc}

    @staticmethod
    def _parse_ocv_curve(
        curve: Any,
    ) -> list[tuple[float, float]] | None:
        if curve is None:
            return None
        if not isinstance(curve, list) or len(curve) < 2:
            raise ApiError(
                422, "invalid_ocv_curve", "ocv_curve must contain at least two points"
            )
        points: list[tuple[float, float]] = []
        previous_voltage: float | None = None
        previous_soc: float | None = None
        for point in curve:
            if not isinstance(point, dict):
                raise ApiError(
                    422, "invalid_ocv_curve", "each OCV point must be an object"
                )
            voltage = point.get("voltage_v")
            soc = point.get("soc")
            if not _is_finite_number(voltage) or not _is_finite_number(soc):
                raise ApiError(
                    422,
                    "invalid_ocv_curve",
                    "OCV point voltage_v and soc must be finite numbers",
                )
            if not 0 <= soc <= 1:
                raise ApiError(
                    422, "invalid_ocv_curve", "OCV point soc must be within [0, 1]"
                )
            if previous_voltage is not None:
                if voltage <= previous_voltage:
                    raise ApiError(
                        422,
                        "invalid_ocv_curve",
                        "OCV point voltage_v must be strictly increasing",
                    )
                if soc < previous_soc:
                    raise ApiError(
                        422,
                        "invalid_ocv_curve",
                        "OCV point soc must be non-decreasing",
                    )
            points.append((voltage, soc))
            previous_voltage = voltage
            previous_soc = soc
        return points

    @staticmethod
    def _parse_options(payload: dict[str, Any]) -> tuple[float, float, float]:
        rest_current = payload.get("rest_current_a", DEFAULT_REST_CURRENT_A)
        rest_duration = payload.get("rest_duration_s", DEFAULT_REST_DURATION_S)
        ocv_weight = payload.get("ocv_weight", DEFAULT_OCV_WEIGHT)
        if (
            not _is_finite_number(rest_current)
            or not _is_finite_number(rest_duration)
            or not _is_finite_number(ocv_weight)
        ):
            raise ApiError(
                422,
                "invalid_options",
                "rest_current_a, rest_duration_s and ocv_weight must be finite numbers",
            )
        if rest_current < 0 or rest_duration < 0 or not 0 <= ocv_weight <= 1:
            raise ApiError(
                422,
                "invalid_options",
                "rest_current_a and rest_duration_s must be non-negative and "
                "ocv_weight must be within [0, 1]",
            )
        return rest_current, rest_duration, ocv_weight

"""HTTP entry point for PowerRail."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .service import ApiError, Service

SOC_ROUTE = "/v1/battery/soc/estimate"


def env_address() -> tuple[str, int]:
    raw = os.environ.get("POWERRAIL_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid POWERRAIL_ADDR: {raw!r}")
    return host, int(port)


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def do_POST(self) -> None:
        if self.path != SOC_ROUTE:
            self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})
            return
        try:
            length = int(self.headers.get("Content-Length", 0))
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            payload = json.loads(raw.decode("utf-8")) if raw else None
        except (json.JSONDecodeError, UnicodeDecodeError):
            self.send_json(
                400, {"error": {"code": "invalid_json", "message": "request body must be valid JSON"}}
            )
            return
        try:
            result = self.service.estimate_soc(payload)
        except ApiError as exc:
            self.send_json(
                exc.status, {"error": {"code": exc.code, "message": exc.message}}
            )
            return
        self.send_json(200, result)

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="powerrail.server", description="电源与能耗管理平台")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"PowerRail listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import unittest

from powerrail.service import ApiError, Service


def base_request(**overrides):
    payload = {
        "capacity_ah": 1.0,
        "initial_soc": 0.8,
        "samples": [
            {"timestamp_s": 0, "current_a": 1.0, "voltage_v": 3.8},
            {"timestamp_s": 1800, "current_a": 1.0, "voltage_v": 3.7},
        ],
    }
    payload.update(overrides)
    return payload


class CoulombCountingTest(unittest.TestCase):
    def setUp(self) -> None:
        self.service = Service()

    def test_first_sample_uses_initial_soc(self) -> None:
        result = self.service.estimate_soc(base_request())
        first = result["estimates"][0]
        self.assertEqual(first["timestamp_s"], 0)
        self.assertEqual(first["soc"], 0.8)
        self.assertEqual(first["source"], "coulomb")

    def test_discharge_with_average_current(self) -> None:
        payload = {
            "capacity_ah": 1.0,
            "initial_soc": 0.8,
            "samples": [
                {"timestamp_s": 0, "current_a": 0.0, "voltage_v": 3.8},
                {"timestamp_s": 1800, "current_a": 2.0, "voltage_v": 3.7},
            ],
        }
        result = self.service.estimate_soc(payload)
        # average current 1.0 A over 1800 s = 0.5 Ah against 1 Ah capacity
        self.assertAlmostEqual(result["estimates"][1]["soc"], 0.3)
        self.assertEqual(result["estimates"][1]["source"], "coulomb")
        self.assertEqual(result["final_soc"], result["estimates"][-1]["soc"])

    def test_charge_moves_soc_up_and_clamps_to_unit_range(self) -> None:
        payload = {
            "capacity_ah": 1.0,
            "initial_soc": 0.95,
            "samples": [
                {"timestamp_s": 0, "current_a": -2.0, "voltage_v": 4.1},
                {"timestamp_s": 3600, "current_a": -2.0, "voltage_v": 4.2},
            ],
        }
        result = self.service.estimate_soc(payload)
        self.assertEqual(result["estimates"][-1]["soc"], 1.0)

    def test_estimates_match_sample_count_and_order(self) -> None:
        payload = {
            "capacity_ah": 2.0,
            "initial_soc": 0.5,
            "samples": [
                {"timestamp_s": 0, "current_a": 1.0, "voltage_v": 4.0},
                {"timestamp_s": 600, "current_a": 1.0, "voltage_v": 3.9},
                {"timestamp_s": 1200, "current_a": 1.0, "voltage_v": 3.8},
                {"timestamp_s": 1800, "current_a": 1.0, "voltage_v": 3.7},
            ],
        }
        result = self.service.estimate_soc(payload)
        self.assertEqual(len(result["estimates"]), 4)
        self.assertEqual(
            [item["timestamp_s"] for item in result["estimates"]], [0, 600, 1200, 1800]
        )
        self.assertEqual(result["final_soc"], result["estimates"][-1]["soc"])


class OcvCorrectionTest(unittest.TestCase):
    def setUp(self) -> None:
        self.service = Service()
        self.curve = [
            {"voltage_v": 3.0, "soc": 0.0},
            {"voltage_v": 4.0, "soc": 1.0},
        ]

    def _rest_payload(self, **overrides):
        payload = {
            "capacity_ah": 1.0,
            "initial_soc": 0.5,
            "ocv_curve": self.curve,
            "samples": [
                {"timestamp_s": 0, "current_a": 0.0, "voltage_v": 3.8},
                {"timestamp_s": 150, "current_a": 0.0, "voltage_v": 3.8},
                {"timestamp_s": 300, "current_a": 0.0, "voltage_v": 3.8},
            ],
        }
        payload.update(overrides)
        return payload

    def test_no_correction_before_rest_duration(self) -> None:
        payload = self._rest_payload(
            samples=[
                {"timestamp_s": 0, "current_a": 0.0, "voltage_v": 3.8},
                {"timestamp_s": 299, "current_a": 0.0, "voltage_v": 3.8},
            ]
        )
        result = self.service.estimate_soc(payload)
        self.assertEqual(result["estimates"][-1]["source"], "coulomb")

    def test_correction_once_rest_duration_reached(self) -> None:
        result = self.service.estimate_soc(self._rest_payload())
        corrected = result["estimates"][-1]
        self.assertEqual(corrected["source"], "ocv_corrected")
        # soc_next stays 0.5 at zero current; OCV interpolation yields 0.8
        self.assertAlmostEqual(corrected["soc"], 0.8 * 0.2 + 0.5 * 0.8)

    def test_current_above_threshold_resets_rest_timer(self) -> None:
        payload = self._rest_payload(
            samples=[
                {"timestamp_s": 0, "current_a": 0.0, "voltage_v": 3.8},
                {"timestamp_s": 200, "current_a": 0.0, "voltage_v": 3.8},
                {"timestamp_s": 400, "current_a": 1.0, "voltage_v": 3.8},
                {"timestamp_s": 600, "current_a": 0.0, "voltage_v": 3.8},
                {"timestamp_s": 800, "current_a": 0.0, "voltage_v": 3.8},
            ]
        )
        result = self.service.estimate_soc(payload)
        self.assertEqual(result["estimates"][-1]["source"], "coulomb")

    def test_interval_boundaries_must_both_be_below_threshold(self) -> None:
        payload = self._rest_payload(
            rest_current_a=0.05,
            samples=[
                {"timestamp_s": 0, "current_a": 0.1, "voltage_v": 3.8},
                {"timestamp_s": 300, "current_a": 0.0, "voltage_v": 3.8},
            ],
        )
        result = self.service.estimate_soc(payload)
        self.assertEqual(result["estimates"][-1]["source"], "coulomb")

    def test_out_of_range_voltage_uses_nearest_endpoint(self) -> None:
        payload = self._rest_payload(
            samples=[
                {"timestamp_s": 0, "current_a": 0.0, "voltage_v": 2.5},
                {"timestamp_s": 150, "current_a": 0.0, "voltage_v": 2.5},
                {"timestamp_s": 300, "current_a": 0.0, "voltage_v": 2.5},
            ]
        )
        result = self.service.estimate_soc(payload)
        corrected = result["estimates"][-1]
        self.assertEqual(corrected["source"], "ocv_corrected")
        self.assertAlmostEqual(corrected["soc"], 0.5 * 0.8)


class ValidationTest(unittest.TestCase):
    def setUp(self) -> None:
        self.service = Service()

    def assert_code(self, payload, code, status=422):
        with self.assertRaises(ApiError) as ctx:
            self.service.estimate_soc(payload)
        self.assertEqual(ctx.exception.code, code)
        self.assertEqual(ctx.exception.status, status)

    def test_non_object_payload_is_invalid_json(self) -> None:
        for payload in (None, [], "text", 5):
            self.assert_code(payload, "invalid_json", status=400)

    def test_capacity_rules(self) -> None:
        self.assert_code(base_request(capacity_ah=None), "invalid_capacity")
        self.assert_code(base_request(capacity_ah=0), "invalid_capacity")
        self.assert_code(base_request(capacity_ah=-1), "invalid_capacity")
        self.assert_code(base_request(capacity_ah=float("nan")), "invalid_capacity")
        self.assert_code(
            {k: v for k, v in base_request().items() if k != "capacity_ah"},
            "invalid_capacity",
        )

    def test_initial_soc_rules(self) -> None:
        self.assert_code(base_request(initial_soc=None), "invalid_initial_soc")
        self.assert_code(base_request(initial_soc=-0.1), "invalid_initial_soc")
        self.assert_code(base_request(initial_soc=1.1), "invalid_initial_soc")
        self.assert_code(base_request(initial_soc=float("inf")), "invalid_initial_soc")

    def test_samples_rules(self) -> None:
        self.assert_code(base_request(samples=[]), "invalid_samples")
        self.assert_code(base_request(samples="x"), "invalid_samples")
        self.assert_code(base_request(samples=None), "invalid_samples")

    def test_timestamp_rules(self) -> None:
        bad_sample = [
            {"timestamp_s": 0, "current_a": 1.0, "voltage_v": 3.8},
            {"timestamp_s": 0, "current_a": 1.0, "voltage_v": 3.8},
        ]
        self.assert_code(base_request(samples=bad_sample), "invalid_timestamp")
        missing = [{"current_a": 1.0, "voltage_v": 3.8}]
        self.assert_code(base_request(samples=missing), "invalid_timestamp")

    def test_measurement_rules(self) -> None:
        missing_current = [
            {"timestamp_s": 0, "voltage_v": 3.8},
            {"timestamp_s": 1, "voltage_v": 3.8},
        ]
        self.assert_code(base_request(samples=missing_current), "invalid_measurement")
        non_finite = [
            {"timestamp_s": 0, "current_a": 1.0, "voltage_v": 3.8},
            {"timestamp_s": 1, "current_a": float("nan"), "voltage_v": 3.8},
        ]
        self.assert_code(base_request(samples=non_finite), "invalid_measurement")

    def test_ocv_curve_rules(self) -> None:
        self.assert_code(
            base_request(ocv_curve=[{"voltage_v": 3.0, "soc": 0.0}]),
            "invalid_ocv_curve",
        )
        self.assert_code(
            base_request(
                ocv_curve=[
                    {"voltage_v": 4.0, "soc": 0.0},
                    {"voltage_v": 3.0, "soc": 1.0},
                ]
            ),
            "invalid_ocv_curve",
        )
        self.assert_code(
            base_request(
                ocv_curve=[
                    {"voltage_v": 3.0, "soc": 0.8},
                    {"voltage_v": 4.0, "soc": 0.2},
                ]
            ),
            "invalid_ocv_curve",
        )
        self.assert_code(
            base_request(
                ocv_curve=[
                    {"voltage_v": 3.0, "soc": 1.2},
                    {"voltage_v": 4.0, "soc": 1.0},
                ]
            ),
            "invalid_ocv_curve",
        )

    def test_option_rules(self) -> None:
        self.assert_code(
            base_request(rest_current_a=-0.01), "invalid_options"
        )
        self.assert_code(
            base_request(rest_duration_s=-1), "invalid_options"
        )
        self.assert_code(base_request(ocv_weight=1.1), "invalid_options")
        self.assert_code(base_request(ocv_weight="x"), "invalid_options")

    def test_custom_options_are_honored(self) -> None:
        curve = [
            {"voltage_v": 3.0, "soc": 0.0},
            {"voltage_v": 4.0, "soc": 1.0},
        ]
        payload = {
            "capacity_ah": 1.0,
            "initial_soc": 0.5,
            "ocv_curve": curve,
            "rest_current_a": 0.5,
            "rest_duration_s": 100,
            "ocv_weight": 0.5,
            "samples": [
                {"timestamp_s": 0, "current_a": 0.0, "voltage_v": 3.8},
                {"timestamp_s": 100, "current_a": 0.0, "voltage_v": 3.8},
            ],
        }
        result = self.service.estimate_soc(payload)
        item = result["estimates"][-1]
        self.assertEqual(item["source"], "ocv_corrected")
        self.assertAlmostEqual(item["soc"], 0.65)


if __name__ == "__main__":
    unittest.main()

